CREATE TABLE TEMPLATE_FIELD
(
    ID                    RAW(16) NOT NULL,
    IS_ACTIVE             NUMBER(1) DEFAULT 1 NOT NULL,
    CREATED_ON            TIMESTAMP WITH TIME ZONE NOT NULL,
    UPDATED_ON            TIMESTAMP WITH TIME ZONE,
    CREATED_BY            VARCHAR2(100),
    UPDATED_BY            VARCHAR2(100),

    TSP_CODE              VARCHAR2(100 CHAR) NOT NULL,
    TAX_CODE              VARCHAR2(100 CHAR) NOT NULL,
    TITLE                 VARCHAR2(250 CHAR) NOT NULL,

    REGEX_PATTERN         VARCHAR2(500 CHAR),
    ERROR_MESSAGE_FA      VARCHAR2(500 CHAR),
    SECOND_ERROR_MESSAGE  VARCHAR2(100 CHAR),

    COMPONENT_TYPE        VARCHAR2(50 CHAR),
    INVOICE_STEP          VARCHAR2(50 CHAR)
);

ALTER TABLE TEMPLATE_FIELD
    ADD CONSTRAINT PK_TEMPLATE_FIELD PRIMARY KEY (ID);

ALTER TABLE TEMPLATE_FIELD
    ADD CONSTRAINT UK_TEMPLATE_FIELD_TSP_CODE UNIQUE (TSP_CODE);

ALTER TABLE TEMPLATE_FIELD
    ADD CONSTRAINT UK_TEMPLATE_FIELD_TAX_CODE UNIQUE (TAX_CODE);


